TEE_Result set_mem_parameters(const struct optee_msg_param_rmem *rmem,
                              struct param_mem *mem) {
    struct TEE_SharedMemory *shmem;

    shmem = TEE_GetSharedMemoryByRef(rmem->shm_ref);
    if (!shmem)
        return TEE_ERROR_BAD_PARAMETERS;

    mem->offset = rmem->offset;
    mem->size = rmem->size;

    if (mem->offset + mem->size > shmem->size) {
        TEE_FreeSharedMemory(shmem);
        return TEE_ERROR_BAD_PARAMETERS;
    }

    mem->memobj = shmem;
    return TEE_SUCCESS;
}

