TEE_Result set_memory_parameters(const struct optee_msg_param_rmem *rmem,
                                 struct param_mem *mem)
{
    TEE_SharedMemory *shm = TEE_GetSharedMemoryByRef(&rmem->shm_ref);
    if (!shm)
        return TEE_ERROR_ITEM_NOT_FOUND;

    uint64_t offset = rmem->offset;
    uint64_t size = rmem->size;

    if (offset > (uint64_t)shm->size || size > (uint64_t)shm->size - offset) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    mem->buffer = (uint8_t *)shm->buffer + offset;
    mem->size = size;

    return TEE_SUCCESS;
}

TEE_Result set_memory_parameters(const struct optee_msg_param_rmem *rmem, struct param_mem *mem) {
    struct shared_mem *smem;

    smem = get_shared_memory(rmem->ref);
